vulnerable_code:
app.delete('/api/messages', async (req, res) => {
  const { ids } = req.body;
  await Message.deleteMany({ _id: { $in: ids } });
  res.send('Messages deleted');
});

corrected_code:
app.delete('/api/messages', async (req, res) => {
  const { ids } = req.body;
  await Message.deleteMany({ _id: { $in: ids }, owner: req.user._id });
  res.send('Messages deleted');
});
